function power(a, b) {
  let r = 1n;
  a %= MOD;
  while (b > 0n) {
    if (b & 1n) r = (r * a) % MOD;
    a = (a * a) % MOD;
    b >>= 1n;
  }
  return r;
}
const fact = new Array(N + 1);
fact[0] = 1n;
for (let i = 1; i <= N; i++) fact[i] = (fact[i - 1] * BigInt(i)) % MOD;
const inv = new Array(N + 1);
inv[N] = power(fact[N], MOD - 2n);
for (let i = N; i >= 1; i--) inv[i - 1] = (inv[i] * BigInt(i)) % MOD;
