#include <bits/stdc++.h>
using namespace std;
int main() {
    int q;
    cin >> q;
    const long long MOD = 1000000007LL;
    vector<pair<int, int>> qs(q);
    int N = 0;
    for (auto &pr : qs) { cin >> pr.first >> pr.second; N = max(N, pr.first); }
    vector<long long> fact(N + 1, 1), inv(N + 1, 1);
    for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
    auto power = [&](long long a, long long b) {
        long long r = 1;
        a %= MOD;
        while (b > 0) {
            if (b & 1) r = r * a % MOD;
            a = a * a % MOD;
            b >>= 1;
        }
        return r;
    };
    inv[N] = power(fact[N], MOD - 2);
    for (int i = N; i >= 1; i--) inv[i - 1] = inv[i] * i % MOD;
    for (auto &pr : qs) {
        int n = pr.first, r = pr.second;
        cout << fact[n] * inv[r] % MOD * inv[n - r] % MOD << "\n";
    }
}

