import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StringTokenizer st = new StringTokenizer(new String(System.in.readAllBytes()));
        int q = Integer.parseInt(st.nextToken());
        final long MOD = 1_000_000_007L;
        int[][] qs = new int[q][2];
        int N = 0;
        for (int i = 0; i < q; i++) {
            qs[i][0] = Integer.parseInt(st.nextToken());
            qs[i][1] = Integer.parseInt(st.nextToken());
            N = Math.max(N, qs[i][0]);
        }
        long[] fact = new long[N + 1];
        long[] inv = new long[N + 1];
        fact[0] = 1;
        for (int i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
        long r = 1, a = fact[N], b = MOD - 2;
        while (b > 0) {
            if ((b & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            b >>= 1;
        }
        inv[N] = r;
        for (int i = N; i >= 1; i--) inv[i - 1] = inv[i] * i % MOD;
        StringBuilder sb = new StringBuilder();
        for (int[] qq : qs) {
            sb.append(fact[qq[0]] * inv[qq[1]] % MOD * inv[qq[0] - qq[1]] % MOD).append('\n');
        }
        System.out.print(sb);
    }
}
